create table if not exists households(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists household_members(household_id uuid references households(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,primary key(household_id,user_id));
create table if not exists tasks(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade not null,name text not null,category text,recurrence text,next_due date,estimated_minutes int default 0,materials jsonb default '[]',completed_at timestamptz,archived boolean default false,created_at timestamptz default now());
create table if not exists todos(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade not null,name text not null,priority text default 'normal',planned_date date,notes text,completed_at timestamptz,created_at timestamptz default now());
create table if not exists shopping(id uuid primary key default gen_random_uuid(),household_id uuid references households(id) on delete cascade not null,name text not null,bought boolean default false,created_at timestamptz default now());
alter table households enable row level security;alter table household_members enable row level security;alter table tasks enable row level security;alter table todos enable row level security;alter table shopping enable row level security;
-- Production policies will restrict every row to households in which auth.uid() is a member.